5.  **`services/settlement-orchestrator-service/src/core/saga.c`:**
    ```c
    // In the saga's event handler
    case EVENT_TRADE_IN_COOLING_OFF:
        saga->state = SAGA_STEP_AWAIT_COOLING_OFF;
        // Logic to schedule a future event, not sleep()
        schedule_delayed_command(saga->id, "EndCoolingOff", saga->config.cooling_off_duration);
        break;
    case EVENT_TRADE_CANCELLED:
        if (saga->state == SAGA_STEP_AWAIT_COOLING_OFF) {
            // perform compensation logic
            terminate_saga(saga, "CancelledByUser");
        }
        break;
    ```

